INSERT INTO `tabEmail Template` VALUES
('Dispatch Notification','2026-09-22 15:20:55.010608','2026-09-22 15:20:55.010608','Administrator','Administrator',0,0,'Your order is out for delivery!',0,NULL,'<h1>Dispatch Notification</h1>\n<h3>Details:</h3>\n<table class=\"table table-bordered small\" style=\"max-width:500px\">\n    <tbody>\n        <tr>\n            <td>Customer\'s Name</td>\n            <td>{{ customer }}</td>\n        </tr>\n        <tr>\n            <td>Contact\'s Name</td>\n            <td>{{ first_name }} {{ last_name }}</td>\n        </tr>\n        <tr>\n            <td>Address Name</td>\n            <td>{{ address }}</td>\n        </tr>\n        <tr>\n            <td>Address Details</td>\n            <td>{{ customer_address }}</td>\n        </tr>\n        <tr>\n            <td>Order Number</td>\n            <td>{{ delivery_note }}</td>\n        </tr>\n        <tr>\n            <td>Order Total</td>\n            <td>{{ grand_total }}</td>\n        </tr>\n        <tr>\n            <td>Departure Time</td>\n            <td>{{ departure_time }}</td>\n        </tr>\n        <tr>\n            <td>Estimated Arrival</td>\n            <td>{{ estimated_arrival }}</td>\n        </tr>\n        <tr>\n            <td>Driver\'s Name</td>\n            <td>{{ driver_name }}</td>\n        </tr>\n        <tr>\n            <td>Driver\'s Number</td>\n            <td>{{ cell_number }}</td>\n        </tr>\n        <tr>\n            <td>Vehicle Number</td>\n            <td>{{ vehicle }}</td>\n        </tr>\n    </tbody>\n</table>\n',NULL,NULL,NULL,NULL,0,NULL),
('Exit Questionnaire Notification','2026-09-22 15:06:17.231289','2026-09-22 15:06:17.231289','Administrator','Administrator',0,0,'Exit Questionnaire Notification',0,NULL,'<h2>Exit Questionnaire</h2>\n<br>\n\n<p>\n	Dear {{ employee_name }},\n	<br><br>\n\n	Thank you for the contribution you have made during your time at {{ company }}. We value your opinion and welcome the feedback on your experience working with us.\n	Request you to take out a few minutes to fill up this Exit Questionnaire.\n	{% set web_form = frappe.db.get_single_value(\'HR Settings\',\'exit_questionnaire_web_form\') %}\n	{% set web_form_link = frappe.utils.get_url(uri=frappe.db.get_value(\'Web Form\', web_form, \'route\')) %}\n\n	<br><br>\n	<a class=\"btn btn-primary\" href=\"{{ web_form_link }}\" target=\"_blank\">{{ _(\'Submit Now\') }}</a>\n</p>\n',NULL,NULL,NULL,NULL,0,NULL),
('Interview Feedback Reminder','2026-09-22 15:06:17.226031','2026-09-22 15:06:17.226031','Administrator','Administrator',0,0,'Interview Feedback Reminder',0,NULL,'<h1>Interview Feedback Reminder</h1>\n\n<p>\n	Interview Feedback for Interview {{ name }} is not submitted yet. Please submit your feedback. Thank you, good day!\n</p>\n',NULL,NULL,NULL,NULL,0,NULL),
('Interview Reminder','2026-09-22 15:06:17.222671','2026-09-22 15:06:17.222671','Administrator','Administrator',0,0,'Interview Reminder',0,NULL,'<h1>Interview Reminder</h1>\n\n<p>\n	Interview: {{name}} is scheduled on {{scheduled_on}} from {{from_time}} to {{to_time}}\n</p>\n',NULL,NULL,NULL,NULL,0,NULL),
('Leave Approval Notification','2026-09-22 15:06:17.212610','2026-09-22 15:06:17.212610','Administrator','Administrator',0,0,'Leave Approval Notification',0,NULL,'<h1>Leave Application Notification</h1>\n<h3>Details:</h3>\n\n	<table class=\"table table-bordered small\" style=\"max-width: 500px;\">\n		<tr>\n			<td>Employee</td>\n			<td>{{employee_name}}</td>\n		</tr>\n		<tr>\n			<td>Leave Type</td>\n			<td>{{leave_type}}</td>\n		</tr>\n		<tr>\n			<td>From Date</td>\n			<td>{{from_date}}</td>\n		</tr>\n		<tr>\n			<td>To Date</td>\n			<td>{{to_date}}</td>\n		</tr>\n		<tr>\n			<td>Status</td>\n			<td>{{status}}</td>\n		</tr>\n	</table>\n\n	{% set doc_link = frappe.utils.get_url_to_form(\'Leave Application\', name) %}\n\n	<br><br>\n	<a class=\"btn btn-primary\" href=\"{{ doc_link }}\" target=\"_blank\">{{ _(\'Open Now\') }}</a>',NULL,NULL,NULL,NULL,0,NULL),
('Leave Status Notification','2026-09-22 15:06:17.218408','2026-09-22 15:06:17.218408','Administrator','Administrator',0,0,'Leave Status Notification',0,NULL,'<h1>Leave Application Notification</h1>\n<h3>Details:</h3>\n\n	<table class=\"table table-bordered small\" style=\"max-width: 500px;\">\n		<tr>\n			<td>Employee</td>\n			<td>{{employee_name}}</td>\n		</tr>\n		<tr>\n			<td>Leave Type</td>\n			<td>{{leave_type}}</td>\n		</tr>\n		<tr>\n			<td>From Date</td>\n			<td>{{from_date}}</td>\n		</tr>\n		<tr>\n			<td>To Date</td>\n			<td>{{to_date}}</td>\n		</tr>\n		<tr>\n			<td>Status</td>\n			<td>{{status}}</td>\n		</tr>\n	</table>\n\n	{% set doc_link = frappe.utils.get_url_to_form(\'Leave Application\', name) %}\n\n	<br><br>\n	<a class=\"btn btn-primary\" href=\"{{ doc_link }}\" target=\"_blank\">{{ _(\'Open Now\') }}</a>',NULL,NULL,NULL,NULL,0,NULL);
/*!40000 ALTER TABLE `tabEmail Template` ENABLE KEYS */;
