('Error Log','2026-09-22 15:04:08.073717','2026-09-22 15:04:08.073717','Administrator','Administrator',0,0,0,0,NULL,'Email',NULL,'[Error] {{ doc.method }}','New','Error Log',NULL,NULL,NULL,0,0,NULL,NULL,NULL,0,'Alert',NULL,NULL,NULL,'Python',NULL,NULL,NULL,NULL,0,'HTML','{% set error_lines = (doc.error or \"\").split(\'\\n\') %}\n{% set first_lines = 10 %}\n{% set last_lines = 15 %}\n{% set max_lines = first_lines + last_lines %}\n{% set total_lines = error_lines | length %}\n{% set needs_truncation = total_lines > max_lines %}\n\n<table class=\"email-header\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\n    <tr>\n        <td>\n            <h1 class=\"email-header-title\">\n                Error Log\n            </h1>\n        </td>\n    </tr>\n</table>\n\n<table class=\"table table-bordered\" width=\"100%\">\n    <tr>\n        <td class=\"text-bold\" style=\"background: #f8f8f8; width: 120px;\">Site</td>\n        <td><a href=\"{{ frappe.utils.get_url() }}\">{{ frappe.utils.get_url() }}</a></td>\n    </tr>\n    <tr>\n        <td class=\"text-bold\" style=\"background: #f8f8f8;\">Error ID</td>\n        <td>{{ frappe.utils.get_link_to_form(\"Error Log\", doc.name, doc.name) }}</td>\n    </tr>\n    <tr>\n        <td class=\"text-bold\" style=\"background: #f8f8f8;\">Title</td>\n        <td>{{ doc.method or \"N/A\" }}</td>\n    </tr>\n    <tr>\n        <td class=\"text-bold\" style=\"background: #f8f8f8;\">Logged At</td>\n        <td>{{ frappe.utils.format_datetime(doc.creation) }}</td>\n    </tr>\n    {% if doc.reference_doctype and doc.reference_name %}\n    <tr>\n        <td class=\"text-bold\" style=\"background: #f8f8f8;\">Reference</td>\n        <td>{{ frappe.utils.get_link_to_form(doc.reference_doctype, doc.reference_name) }}</td>\n    </tr>\n    {% endif %}\n</table>\n\n<div style=\"margin-top: 20px;\">\n    <div class=\"text-medium text-bold\">\n        Error Details\n        {% if needs_truncation %}\n        <span class=\"text-muted\" style=\"font-weight: normal;\"> ({{ max_lines }} of {{ total_lines }} lines)</span>\n        {% endif %}\n    </div>\n    <div class=\"gray-container\" style=\"margin-top: 8px;\">\n        <pre class=\"text-small\" style=\"margin: 0; white-space: pre-wrap; word-wrap: break-word;\">{% if needs_truncation %}{{ error_lines[:first_lines] | join(\'\\n\') }}\n\n<span class=\"text-muted\" style=\"font-style: italic;\">... {{ total_lines - max_lines }} lines omitted ...</span>\n\n{{ error_lines[-last_lines:] | join(\'\\n\') }}{% else %}{{ error_lines | join(\'\\n\') }}{% endif %}</pre>\n    </div>\n</div>\n\n<div class=\"more-info\">\n    <a href=\"{{ frappe.utils.get_url_to_form(\'Error Log\', doc.name) }}\" class=\"btn btn-primary\">View Error Log</a>\n</div>\n\n<p class=\"text-muted text-small\" style=\"margin-top: 20px;\">\n    This is an automated notification from {{ frappe.utils.get_host_name() }}.\n</p>',0,NULL,'',NULL,NULL,NULL,NULL,NULL),
('Exit Interview Scheduled','2021-12-05 22:11:47.263933','2021-12-05 22:26:57.096159','Administrator','Administrator',0,0,1,1,'HR','Email',NULL,'Exit Interview Scheduled: {{ doc.name }}','Days Before','Exit Interview',NULL,'date',NULL,1,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,'doc.date and doc.email and doc.docstatus != 2 and doc.status == \'Scheduled\'',NULL,NULL,NULL,1,NULL,'<table class=\"panel-header\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\n	<tr height=\"10\"></tr>\n	<tr>\n		<td width=\"15\"></td>\n		<td>\n			<div class=\"text-medium text-muted\">\n				<span>{{_(\"Exit Interview Scheduled:\")}} {{ doc.name }}</span>\n			</div>\n		</td>\n		<td width=\"15\"></td>\n	</tr>\n	<tr height=\"10\"></tr>\n</table>\n\n<table class=\"panel-body\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\n	<tr height=\"10\"></tr>\n	<tr>\n		<td width=\"15\"></td>\n		<td>\n			<div>\n				<ul class=\"list-unstyled\" style=\"line-height: 1.7\">\n					<li>{{_(\"Employee\")}}: <b>{{ doc.employee }} - {{ doc.employee_name }}</b></li>\n					<li>{{_(\"Date\")}}: <b>{{ doc.date }}</b></li>\n					<li> {{_(\"Interviewers\")}}: </li>\n					{% for entry in doc.interviewers %}\n						<ul>\n							<li>{{ entry.user }}</li>\n						</ul>\n					{% endfor %}\n					<li>{{ _(\"Interview Document\") }}: {{ frappe.utils.get_link_to_form(doc.doctype, doc.name) }}</li>\n				</ul>\n			</div>\n		</td>\n		<td width=\"15\"></td>\n	</tr>\n	<tr height=\"10\"></tr>\n</table>\n',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Integration Request','2026-09-22 15:04:08.064386','2026-09-22 15:04:08.064386','Administrator','Administrator',0,0,0,0,NULL,'Email',NULL,'[Error] {{ doc.integration_request_service }}','Save','Integration Request',NULL,NULL,NULL,0,0,NULL,NULL,NULL,0,'Alert',NULL,NULL,NULL,'Python','doc.status==\"Failed\"',NULL,NULL,NULL,0,'HTML','{% set error_lines = (doc.error or \"\").split(\'\\n\') %}\n{% set output_lines = (doc.output or \"\").split(\'\\n\') %}\n{% set first_lines = 10 %}\n{% set last_lines = 15 %}\n{% set max_lines = first_lines + last_lines %}\n{% set total_error_lines = error_lines | length %}\n{% set error_needs_truncation = total_error_lines > max_lines %}\n{% set total_output_lines = output_lines | length %}\n{% set output_needs_truncation = total_output_lines > max_lines %}\n\n<table class=\"email-header\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\n	<tr>\n		<td>\n			<h1 class=\"email-header-title\">\n				Integration Request\n			</h1>\n		</td>\n	</tr>\n</table>\n\n<table class=\"table table-bordered\" style=\"width: 100%;\">\n	<tr>\n		<td class=\"text-bold\" style=\"background: #f8f8f8; width: 120px\">Site</td>\n		<td><a href=\"{{ frappe.utils.get_url() }}\">{{ frappe.utils.get_url() }}</a></td>\n	</tr>\n	<tr>\n		<td class=\"text-bold\" style=\"background: #f8f8f8;\">Request ID</td>\n		<td>{{ frappe.utils.get_link_to_form(\"Integration Request\", doc.name, doc.request_id or\n			doc.name) }}</td>\n	</tr>\n	<tr>\n		<td class=\"text-bold\" style=\"background: #f8f8f8;\">Service</td>\n		<td>{{ doc.integration_request_service or \"N/A\" }}</td>\n	</tr>\n	<tr>\n		<td class=\"text-bold\" style=\"background: #f8f8f8;\">Status</td>\n		<td>{{ doc.status }}</td>\n	</tr>\n	{% if doc.request_description %}\n	<tr>\n		<td class=\"text-bold\" style=\"background: #f8f8f8;\">Description</td>\n		<td>{{ doc.request_description }}</td>\n	</tr>\n	{% endif %}\n	<tr>\n		<td class=\"text-bold\" style=\"background: #f8f8f8;\">Logged At</td>\n		<td>{{ frappe.utils.format_datetime(doc.creation) }}</td>\n	</tr>\n	{% if doc.url %}\n	<tr>\n		<td class=\"text-bold\" style=\"background: #f8f8f8;\">Endpoint URL</td>\n		<td class=\"text-small\" style=\"word-break: break-all;\"><a href=\"{{ doc.url }}\">{{ doc.url}}</a></td>\n	</tr>\n	{% endif %}\n	{% if doc.reference_doctype and doc.reference_docname %}\n	<tr>\n		<td class=\"text-bold\" style=\"background: #f8f8f8;\">Reference</td>\n		<td>\n			<a\n				href=\"{{ frappe.utils.get_url_to_form(doc.reference_doctype, doc.reference_docname) }}\">\n				{{ doc.reference_doctype }}: {{ doc.reference_docname }}\n			</a>\n		</td>\n	</tr>\n	{% endif %}\n</table>\n\n{% if doc.error %}\n<div style=\"margin-top: 20px;\">\n	<div class=\"text-medium text-bold\">\n		Error Details\n		{% if error_needs_truncation %}\n		<span class=\"text-muted\" style=\"font-weight: normal;\"> ({{ max_lines }} of {{\n			total_error_lines }} lines)</span>\n		{% endif %}\n	</div>\n	<div class=\"gray-container\" style=\"margin-top: 8px;\">\n		<pre class=\"text-small\"\n			style=\"margin: 0; white-space: pre-wrap; word-wrap: break-word;\">{% if error_needs_truncation %}{{ error_lines[:first_lines] | join(\'\\n\') }}\n\n<span class=\"text-muted\" style=\"font-style: italic;\">... {{ total_error_lines - max_lines }} lines omitted ...</span>\n\n{{ error_lines[-last_lines:] | join(\'\\n\') }}{% else %}{{ error_lines | join(\'\\n\') }}{% endif %}</pre>\n	</div>\n</div>\n{% endif %}\n\n{% if doc.output %}\n<div style=\"margin-top: 20px;\">\n	<div class=\"text-medium text-bold\">\n		Response Output\n		{% if output_needs_truncation %}\n		<span class=\"text-muted\" style=\"font-weight: normal;\"> ({{ max_lines }} of {{\n			total_output_lines }} lines)</span>\n		{% endif %}\n	</div>\n	<div class=\"gray-container\" style=\"margin-top: 8px;\">\n		<pre class=\"text-small\"\n			style=\"margin: 0; white-space: pre-wrap; word-wrap: break-word;\">{% if output_needs_truncation %}{{ output_lines[:first_lines] | join(\'\\n\') }}\n\n<span class=\"text-muted\" style=\"font-style: italic;\">... {{ total_output_lines - max_lines }} lines omitted ...</span>\n\n{{ output_lines[-last_lines:] | join(\'\\n\') }}{% else %}{{ output_lines | join(\'\\n\') }}{% endif %}</pre>\n	</div>\n</div>\n{% endif %}\n\n<div class=\"more-info\">\n	<a class=\"btn btn-primary\"\n		href=\"{{ frappe.utils.get_url_to_form(\'Integration Request\', doc.name) }}\">\n		View Integration Request\n	</a>\n</div>\n\n<p class=\"text-muted text-small\" style=\"margin-top: 20px;\">\n	This is an automated notification from {{ frappe.utils.get_host_name() }}.\n</p>',0,NULL,'',NULL,NULL,NULL,NULL,NULL),
('Material Request Receipt Notification','2019-04-29 11:53:23.981418','2026-02-23 17:41:43.982194','Administrator','Administrator',0,0,1,1,'Manufacturing','Email',NULL,'{{ doc.name }} has been received','Value Change','Material Request','',NULL,NULL,0,0,NULL,'status',NULL,0,NULL,NULL,NULL,'','Python','doc.status == \"Received\" or doc.status == \"Partially Received\"',NULL,NULL,NULL,0,'HTML','<p><b>{{ _(\"Material Request Type\") }}</b>: {{ doc.material_request_type }}<br>\n<b>{{ _(\"Company\") }}</b>: {{ doc.company }}</p>\n\n<h3>{{ _(\"Order Summary\") }}</h3>\n\n<table border=2 >\n    <tr align=\"center\">\n        <th>{{ _(\"Item Name\") }}</th>\n        <th>{{ _(\"Received Quantity\") }}</th>\n    </tr>\n    {% for item in doc.items %}\n        {% if frappe.utils.flt(item.received_qty, 2) > 0.0 %}\n            <tr align=\"center\">\n                <td>{{ item.item_code }}</td>\n                <td>{{ frappe.utils.flt(item.received_qty, 2) }}</td>\n            </tr>\n        {% endif %}\n    {% endfor %}\n</table>\n',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Notification for new fiscal year','2018-04-25 14:19:05.440361','2026-02-23 17:37:03.755394','Administrator','Administrator',0,0,1,1,'Accounts','Email',NULL,'New Fiscal Year {{ doc.name }} - Review Required','New','Fiscal Year',NULL,NULL,NULL,0,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,'Python','doc.auto_created == 1',NULL,NULL,NULL,0,'HTML','<h4>{{ _(\"New Fiscal Year - {0}\").format(doc.name) }}</h4>\n\n<p>{{ _(\"A new fiscal year has been automatically created.\") }}</p>\n\n<p>{{ _(\"Fiscal Year Details\") }}</p>\n\n<table style=\"margin-bottom: 1rem; width: 70%\">\n    <tr>\n        <td style=\"font-weight:bold; width: 40%\">{{ _(\"Year Name\") }}</td>\n        <td>{{ doc.name }}</td>\n    </tr>\n    <tr>\n        <td style=\"font-weight:bold; width: 40%\">{{ _(\"Start Date\") }}</td>\n        <td>{{ frappe.format_value(doc.year_start_date) }}</td>\n    </tr>\n    <tr>\n        <td style=\"font-weight:bold; width: 40%\">{{ _(\"End Date\") }}</td>\n        <td>{{ frappe.format_value(doc.year_end_date) }}</td>\n    </tr>\n    {% if doc.companies|length > 0 %}\n    <tr>\n        <td style=\"vertical-align: top; font-weight: bold; width: 40%\" rowspan=\"{{ doc.companies|length }}\">\n        {% if doc.companies|length < 2 %}\n            {{ _(\"Company\") }}\n        {% else %}\n            {{ _(\"Companies\") }}\n        {% endif %}\n        </td>\n        <td>{{ doc.companies[0].company }}</td>\n    </tr>\n    {% for idx in range(1, doc.companies|length) %}\n    <tr>\n        <td>{{ doc.companies[idx].company }}</td>\n    </tr>\n    {% endfor %}\n    {% endif %}\n</table>\n\n{% if doc.disabled %}\n<p>{{ _(\"The fiscal year has been automatically created in a Disabled state to maintain consistency with the previous fiscal year\'s status.\") }}</p>\n{% endif %}\n\n<p>{{ _(\"Please review the {0} configuration and complete any required financial setup activities.\").format(frappe.utils.get_link_to_form(\"Fiscal Year\", doc.name, frappe.bold(\"Fiscal Year\"))) }}</p>',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Retention Bonus','2018-05-15 18:52:36.362838','2018-05-15 19:00:24.294418','Administrator','Administrator',0,0,1,1,'Payroll','Email',NULL,'Retention Bonus alert for {{ doc.employee }}','Days Before','Retention Bonus',NULL,'bonus_payment_date',NULL,14,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,'doc.docstatus==1',NULL,NULL,NULL,0,NULL,'<p>{{ _(\"Hello\") }},</p>\n\n<p> {{ _(\"Retention Bonus for\") }} {{ doc.employee_name }} {{ _(\"due on\") }} {{ doc.bonus_payment_date }}</p>',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Training Feedback','2017-08-11 03:17:11.769210','2017-08-11 04:26:58.194793','Administrator','Administrator',0,0,1,1,'HR','Email',NULL,'Please Share your Feedback For {{ doc.training_event }}','Submit','Training Result',NULL,NULL,NULL,0,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,'<h3>{{_(\"Training Event\")}}</h3>\n<p>{{ message }}</p>\n\n<h4>{{_(\"Details\")}}</h4>\n{{_(\"Event Name\")}}: <a href=\"{{ event_link }}\">{{ name }}</a>\n<br>{{_(\"Event Location\")}}: {{ location }}\n<br>{{_(\"Start Time\")}}: {{ start_time }}\n<br>{{_(\"End Time\")}}: {{ end_time }}\n<br>{{_(\"Attendance\")}}: {{ attendance }}\n',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Training Scheduled','2017-08-11 03:13:40.519614','2021-06-16 14:08:12.933367','Administrator','Administrator',0,0,1,1,'HR','Email',NULL,'Training Scheduled: {{ doc.name }}','Submit','Training Event',NULL,NULL,NULL,0,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,0,NULL,'<table class=\"panel-header\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\n    <tr height=\"10\"></tr>\n    <tr>\n        <td width=\"15\"></td>\n        <td>\n            <div class=\"text-medium text-muted\">\n                <span>{{_(\"Training Event:\")}} {{ doc.event_name }}</span>\n            </div>\n        </td>\n        <td width=\"15\"></td>\n    </tr>\n    <tr height=\"10\"></tr>\n</table>\n\n<table class=\"panel-body\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\n    <tr height=\"10\"></tr>\n    <tr>\n        <td width=\"15\"></td>\n        <td>\n            <div>\n                {{ doc.introduction }}\n                <ul class=\"list-unstyled\" style=\"line-height: 1.7\">\n                    <li>{{_(\"Event Location\")}}: <b>{{ doc.location }}</b></li>\n                    {% set start = frappe.utils.get_datetime(doc.start_time) %}\n                    {% set end = frappe.utils.get_datetime(doc.end_time) %}\n                    {% if start.date() == end.date() %}\n                        <li>{{_(\"Date\")}}: <b>{{ start.strftime(\"%A, %d %b %Y\") }}</b></li>\n                        <li>\n                            {{_(\"Timing\")}}: <b>{{ start.strftime(\"%I:%M %p\") + \' to \' + end.strftime(\"%I:%M %p\") }}</b>\n                        </li>\n                    {% else %}\n                        <li>\n                            {{_(\"Start Time\")}}: <b>{{ start.strftime(\"%A, %d %b %Y at %I:%M %p\") }}</b>\n                        </li>\n                        <li>{{_(\"End Time\")}}: <b>{{ end.strftime(\"%A, %d %b %Y at %I:%M %p\") }}</b></li>\n                    {% endif %}\n                    <li>{{ _(\"Event Link\") }}: {{ frappe.utils.get_link_to_form(doc.doctype, doc.name) }}</li>\n                    {% if doc.is_mandatory %}\n                        <li>{{ _(\"Note: This Training Event is mandatory\") }}</li>\n                    {% endif %}\n                </ul>\n            </div>\n        </td>\n        <td width=\"15\"></td>\n    </tr>\n    <tr height=\"10\"></tr>\n</table>',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
